INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '"Preparatory work"', 'Per EY''s and Aurifer''s own trackers, both mid-2026');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE code = 'BH';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'No format exists — because e-invoicing remains voluntary', NULL, NULL, 'Bahrain has never published an e-invoicing schema, XML/UBL standard, or technical specification. There is no NBR e-invoicing platform, and Bahrain is confirmed not to be a member of the Peppol network. Businesses that voluntarily issue electronic invoices do so on their own systems, under ordinary VAT invoicing rules, not any e-invoicing-specific format.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE code = 'BH';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s covered today', '[["B2B", "Not defined -- no mandate exists"], ["B2G", "Not defined -- no mandate exists"], ["B2C", "Not defined -- no mandate exists"], ["Voluntary e-invoicing", "Permitted without prior NBR approval, since 16 Nov 2023"]]', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE code = 'BH';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Preparatory signals, not a mandate', '[["2023 platform tender", "Confirmed via Bahrain''s own Tender Board (305/2023/BTB): a 54-month contract to design/operate an e-invoicing platform"], ["2025 tender (reported)", "A further tender for a nationwide B2B system was reported by one industry brief -- could not be independently corroborated this round"], ["Expected model", "Industry commentary speculates a Saudi ZATCA-style approach -- not an official Bahraini government decision"], ["Peppol membership", "Bahrain is not a Peppol member"]]', 'A government tender to build a platform is real preparatory activity, but it is not a law, a mandate, or a dated legal requirement -- included here for completeness, not as evidence a mandate is imminent.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE code = 'BH';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚖️ No e-invoicing penalty schedule exists', NULL, NULL, 'There is nothing to penalize on the e-invoicing side: Bahrain has never legislated an e-invoicing mandate, so no fine or sanction schedule attaches to how (or whether) you issue invoices electronically.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE code = 'BH';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📋 Bahrain''s general VAT penalties (unrelated to e-invoicing)', NULL, NULL, 'Bahrain''s ordinary VAT law carries its own general penalties -- late filing/payment (5-25% of tax due), failure to register (fine up to BHD 10,000), invoice-procedure violations (fine up to BHD 5,000), and tax evasion including non-issuance of invoices (imprisonment plus fines). These apply to VAT compliance broadly and are not specific to e-invoicing; the figures come from a secondary compliance source and were not independently re-verified against the primary VAT law text this research round.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE code = 'BH';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🌍 Context: one of two GCC states with no mandate at all', NULL, NULL, 'Saudi Arabia''s Fatoora system is live and mature; the UAE is phasing in a Peppol-based B2B mandate from July 2026; Oman has a live pilot; Qatar approved a draft law on 6 May 2026. Bahrain and Kuwait are now the only two GCC states with no formal step toward e-invoicing at all.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE code = 'BH';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'There is nothing to comply with today', 'No e-invoicing mandate exists in Bahrain, proposed or enacted. No registration, filing, or format change is required.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE code = 'BH';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'E-invoicing is available voluntarily, with no approval needed', 'Since Nov 2023, any VAT-registered business may issue electronic invoices without seeking NBR''s prior approval -- but nothing requires you to, and no format or platform is mandated.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE code = 'BH';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Watch for a real proposal, not just a tender', 'Bahrain has issued government tenders for e-invoicing platform infrastructure, but a tender is not a mandate. Watch specifically for a draft VAT law amendment or NBR mandate announcement.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE code = 'BH';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Expect Bahrain to follow regional precedent eventually', 'With Saudi Arabia, the UAE, Oman, and now Qatar all moving on e-invoicing, Bahrain is likely to eventually follow -- but nothing officially confirms a timeline, and this page will not speculate on one.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE code = 'BH';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Bookmark this page', 'This tracker will add a real milestone and a proper compliance timeline the moment Bahrain publishes an actual e-invoicing proposal or draft law.');
